/* Original practice aligned to STS 2.B.1–2.B.5 and the local AP archetype cards.
   Numerical options stay in ascending order; conceptual options rotate positions. */
const unitBSections=[
 {id:'2.B.1',title:'Discrete Random Variables',intro:'Build probability distributions and interpret expected value, variance, and standard deviation.',ced:['2.8','2.9']},
 {id:'2.B.2',title:'The Binomial Distribution',intro:'Check the conditions, translate the event, and calculate binomial probabilities and summaries.',ced:['2.10']},
 {id:'2.B.3',title:'The Empirical Rule & Standard Normal Curve',intro:'Connect continuous probability, normal curves, standard scores, and the 68–95–99.7 rule.',ced:['2.11']},
 {id:'2.B.4',title:'Normal Calculations',intro:'Find normal probabilities, percentile cutoffs, and missing parameters.',ced:['2.11']},
 {id:'2.B.5',title:'Intro to Sampling Distributions',intro:'Distinguish populations, samples, and sampling distributions; explain simulation and the central limit theorem.',ced:['2.12']}
];
const bTable=(caption,heads,rows)=>'<div class="table-scroll"><table><caption>'+caption+'</caption><thead><tr>'+heads.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((v,i)=>i?'<td>'+v+'</td>':'<th scope="row">'+v+'</th>').join('')+'</tr>').join('')+'</tbody></table></div>';
const bDistribution=bTable('Number of repair calls in one day',['x','0','1','2','3'],[['P(X = x)','0.15','0.35','0.30','0.20']]);
const bPrize=bTable('Prize from a scratch card',['Prize ($)','0','5','20'],[['Probability','0.70','0.20','0.10']]);
const bSDTable=bTable('Packages returned in one day; μ = 1.4 packages',['x','0','1','2','3'],[['P(X = x)','0.20','0.40','0.20','0.20'],['(x − μ)²','1.96','0.16','0.36','2.56']]);
const bF=n=>Number(n).toFixed(4);
const bChoose=(n,k)=>{let r=1;for(let i=1;i<=k;i++)r=r*(n-i+1)/i;return r};
const bPMF=(n,p,k)=>bChoose(n,k)*p**k*(1-p)**(n-k);
const bBin=(n,p,a,z)=>{let r=0;for(let k=a;k<=z;k++)r+=bPMF(n,p,k);return r};
function bPhi(z){const t=1/(1+.2316419*Math.abs(z)),d=.3989422804014327*Math.exp(-z*z/2);const q=d*t*(.319381530+t*(-.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));return z>=0?1-q:q}
function bInv(p){let a=-9,b=9;for(let i=0;i<65;i++){const m=(a+b)/2;if(bPhi(m)<p)a=m;else b=m}return(a+b)/2}
const bNormal=(a,b,mu,sd)=>bPhi((b-mu)/sd)-bPhi((a-mu)/sd);
const bArithmetic=(entry,result,note)=>({needed:true,steps:[{title:'Open the main menu',keys:['MENU'],mode:'menu',input:'',result:'',note:'Choose Run-Matrix for an arithmetic calculation.'},{title:'Open Run-Matrix',keys:['1'],mode:'run',input:'',result:'',note:'Press 1 to open Run-Matrix.'},{title:'Evaluate the expression',keys:['AC',...entry.split('').map(c=>({'*':'MUL','/':'DIV','+':'ADD','-':'SUB','(':'LP',')':'RP','.':'DOT','^':'POW'}[c]||c)),'EXE'],entry,mode:'result',input:entry,result:String(result),note} ]});
const bGuide=(name,fields,result,extra='')=>({needed:false,distribution:{name,fields,result,extra}});
const bBinGuide=(n,p,a,b)=>bGuide(a===b?'Binomial PD':'Binomial CD',a===b?[['x',a],['Numtrial',n],['p',p]]:[['Lower',a],['Upper',b],['Numtrial',n],['p',p]],bF(bBin(n,p,a,b)),'The bounds are inclusive whole-number counts.');
const bNormGuide=(lo,hi,mu,sd)=>bGuide('Normal CD',[['Lower',lo===-Infinity?'−1 × 10⁹⁹':lo],['Upper',hi===Infinity?'1 × 10⁹⁹':hi],['σ',sd],['μ',mu]],bF(bNormal(lo,hi,mu,sd)),'For an unbounded tail, the very large bound approximates infinity.');
const bInvGuide=(area,mu,sd)=>bGuide('Inverse Normal',[['Tail','Left'],['Area',area],['σ',sd],['μ',mu]],(mu+sd*bInv(area)).toFixed(2),'Area is the proportion to the left of the required cutoff.');
const bQuestions=[];
function bQ(lesson,archetype,scenario,ask,options,key,steps,trap,guide,visual=''){
 const numerical=options.every(o=>/^[-−$\d.]/.test(String(o))&&!/[A-Za-z]/.test(String(o)));
 const ordered=options.map((text,i)=>({text,key:i===key}));
 if(numerical)ordered.sort((a,b)=>Number(String(a.text).replace(/[$−]/g,c=>c==='−'?'-':''))-Number(String(b.text).replace(/[$−]/g,c=>c==='−'?'-':'')));
 else {const r=(bQuestions.length*3+1)%4;ordered.push(...ordered.splice(0,r));}
 bQuestions.push({lesson,archetype,scenario,ask,options:ordered.map(o=>o.text),key:ordered.findIndex(o=>o.key),steps,trap,guide:guide||{needed:false,reason:'Use the definition and reasoning in the explanation; no calculator is needed.'},visual});
}
// 2.B.1: probability distributions, expected value, and spread.
bQ(1,'discrete_or_continuous_variable','A recreation center records four quantities for a randomly selected day.','Which quantity is a discrete random variable?',['The total mass of lost property','The number of court reservations canceled','The time until the first visitor arrives','The volume of drinking water used'],1,['A discrete variable has a countable set of possible values.','The number of canceled reservations is a count: 0, 1, 2, and so on.','Mass, elapsed time, and volume are measurements modeled as continuous.'],'A quantity reported with a number can still be continuous. Counts and measurements are different.');
bQ(1,'valid_probability_distribution','A machine issues a coupon worth $0, $2, or $5. The probabilities of the first two values are 0.45 and 0.35.','What probability must be assigned to the $5 coupon?',['0.10','0.20','0.35','0.80'],1,['A probability distribution must have probabilities between 0 and 1 whose sum is 1.','The missing probability is 1 − 0.45 − 0.35 = 0.20.'],'The probabilities, rather than the dollar values, must add to 1.',bArithmetic('1-0.45-0.35','0.2','The remaining probability completes the distribution.'));
bQ(1,'expected_value_of_discrete_random_variable','Let X be the number of repair calls a technician receives on a randomly selected day.','What is the expected number of calls per day?',['1.50','1.55','2.00','6.00'],1,['Weight each number of calls by its probability.','E(X) = 0(0.15) + 1(0.35) + 2(0.30) + 3(0.20) = 1.55 calls.','Over many days, the average number of calls per day approaches 1.55.'],'The unweighted mean of the four possible counts is 1.50; it ignores how often each count occurs.',bArithmetic('0*0.15+1*0.35+2*0.30+3*0.20','1.55','Multiply each outcome by its probability, then add.'),bDistribution);
bQ(1,'interpret_mean_of_random_variable','A shuttle company models the number of empty seats on a trip by a random variable X with E(X) = 2.4 seats.','Which statement correctly interprets this mean?',['Every trip has exactly 2.4 empty seats.','On each trip, the empty-seat count is 2.4 seats away from its mean.','Over many trips, the average number of empty seats per trip is about 2.4.','There is a 24% chance of an empty seat on the next trip.'],2,['Expected value describes an average over many repetitions of the chance process.','Here the repetitions are shuttle trips and the variable is the number of empty seats.','The long-run average is about 2.4 empty seats per trip, even though a single trip has a whole-number count.'],'An expected count need not be a possible individual outcome.');
bQ(1,'expected_value_of_discrete_random_variable','A scratch card costs $4. Its prize distribution is shown. Let G be the player’s net gain, including the cost of the card.','What is E(G), in dollars?',['−1.00','0.00','3.00','7.00'],0,['The expected prize is 0(0.70) + 5(0.20) + 20(0.10) = $3.','Subtract the $4 cost on every play: E(G) = 3 − 4 = −$1.','A player loses an average of $1 per card over many plays.'],'The expected prize is not the expected net gain. The cost also applies when the prize is zero.',bArithmetic('0*0.70+5*0.20+20*0.10-4','-1','Subtract the cost after calculating the expected prize.'),bPrize);
bQ(1,'standard_deviation_of_discrete_random_variable','X is the number of packages returned to a small store in a day. Its mean is 1.4 packages.','Which value is closest to the standard deviation of X?',['1.02','1.04','1.12','1.29'],0,['Compute the weighted sum of squared deviations.','Var(X) = 1.96(0.20) + 0.16(0.40) + 0.36(0.20) + 2.56(0.20) = 1.04.','SD(X) = √1.04 ≈ 1.02 packages.'],'The variance, 1.04, is in squared packages. Take its square root for standard deviation.',bArithmetic('1.04^0.5','1.019803903','Take the square root of the weighted variance.'),bSDTable);
bQ(1,'interpret_standard_deviation_of_random_variable','The daily number of deliveries has mean 18 deliveries and standard deviation 3 deliveries.','Which statement correctly interprets the standard deviation?',['The average number of deliveries is 3 per day.','Every day has exactly 15 or exactly 21 deliveries.','The mean for any sample of days is exactly 3 deliveries away from 18.','Daily delivery counts typically differ from the mean of 18 by about 3 deliveries.'],3,['Standard deviation describes the typical distance of individual values from the mean.','Here the individual values are daily delivery counts.','Their typical distance from 18 deliveries is about 3 deliveries.'],'Standard deviation describes variability; it is not a guarantee about every day or a mean.');
bQ(1,'expected_value_of_discrete_random_variable','A game pays $12 with probability 0.25 and $0 otherwise. A player pays a fixed entry fee c.','What fee makes the player’s expected net gain equal to zero?',['$0.25','$3.00','$9.00','$12.00'],1,['The expected prize is 12(0.25) + 0(0.75) = $3.','Expected net gain is 3 − c.','Set 3 − c = 0, giving c = $3.'],'A fair fee equals the expected prize, rather than the largest prize.',bArithmetic('12*0.25','3','This is the expected prize and therefore the fair entry fee.'));
bQ(1,'proportion_in_interval_from_cumulative_table','The cumulative distribution for a kiosk’s daily number X of refunds is shown.','What is P(1 < X ≤ 3)?',['0.20','0.30','0.40','0.85'],2,['The desired event contains X = 2 and X = 3.','Subtract the cumulative probability through 1 from the cumulative probability through 3.','P(1 < X ≤ 3) = 0.85 − 0.45 = 0.40.'],'Do not subtract P(X ≤ 0): that would incorrectly include X = 1.',bArithmetic('0.85-0.45','0.4','Subtract the lower cumulative total from the upper cumulative total.'),bTable('Cumulative refund probabilities',['x','0','1','2','3','4'],[['P(X ≤ x)','0.20','0.45','0.70','0.85','1.00']]));
bQ(1,'expected_value_of_discrete_random_variable','The number X of souvenir badges sold by a volunteer in an hour takes values 0, 1, and k, with probabilities 0.20, 0.50, and 0.30. The expected number sold is 1.7.','What is k?',['2','3','4','5'],2,['Use the weighted mean: 0(0.20) + 1(0.50) + k(0.30) = 1.7.','Solve 0.50 + 0.30k = 1.7.','k = (1.7 − 0.50)/0.30 = 4.'],'The outcomes are not equally likely, so their unweighted average is not the expected value.',bArithmetic('(1.7-0.5)/0.3','4','Solve the expected-value equation for the unknown outcome.'));
// 2.B.2: conditions, parameters, exact and cumulative binomial probabilities.
bQ(2,'identify_binomial_setting','In each situation, X is the quantity described.','Which situation makes X a binomial random variable?',['Ten independent serves, each with success probability 0.70; X counts successful serves.','Serve until the first success; X counts the number of serves.','Ten serves with success probabilities increasing after each serve; X counts successes.','Ten independent serves, each with success probability 0.70; X is the total flight time.'],0,['A binomial variable counts successes in a fixed number of independent trials with the same success probability.','The first described setting has n = 10, p = 0.70, two outcomes on each trial, and X counts successes.','The other settings lack a fixed trial count, constant probability, or a success-count variable.'],'Randomness alone does not make a variable binomial. Check what X counts.');
bQ(2,'identify_binomial_setting','A box contains 8 blue and 4 yellow tokens. Five tokens are drawn at random without replacement. X counts the blue tokens drawn.','Why is the exact distribution of X not binomial?',['Five is fewer than 30.','There are more than two tokens in the box.','The draws are dependent and the probability of blue changes after each draw.','The number of blue tokens in the sample is not stated.'],2,['A binomial model requires independent trials with a constant success probability.','Without replacement, the remaining mix changes after a token is drawn.','Sampling 5 of only 12 tokens is too large a fraction to treat this dependence as negligible.'],'A sample size of 30 is not a binomial condition.');
bQ(2,'identify_binomial_quantity_meaning','A seed germinates with probability 0.60. Eight seeds are planted independently.','What does C(8, 3)(0.60)³(0.40)⁵ represent?',['The expected number of seeds that germinate.','The probability that exactly three of the eight seeds germinate.','The probability that at most three seeds germinate.','The probability that the first three seeds germinate, regardless of the others.'],1,['The binomial coefficient counts which three of the eight seeds germinate.','The product (0.60)³(0.40)⁵ gives the probability of one specified arrangement with three successes and five failures.','Multiplying gives P(X = 3), the probability of exactly three germinations.'],'At most three would require adding probabilities for 0, 1, 2, and 3 germinations.');
bQ(2,'binomial_probability_calculation','Each of 10 independently inspected components has probability 0.20 of failing a stress test. Let X count the failed components.','What is P(X = 3), approximately?',[bF(bPMF(10,.2,3)/120),bF(bPMF(10,.2,3)),bF(bBin(10,.2,0,3)),bF(1-bPMF(10,.2,3))],1,['X follows a binomial distribution with n = 10 and p = 0.20.','P(X = 3) = C(10, 3)(0.20)³(0.80)⁷.','The probability is approximately '+bF(bPMF(10,.2,3))+'.'],'The binomial coefficient accounts for all arrangements of the three failed components.',bBinGuide(10,.2,3,3));
bQ(2,'binomial_probability_calculation','A text-message link is opened with probability 0.30, independently for each of 8 recipients. X counts the recipients who open it.','What is the probability that at most two recipients open the link?',[bF(bPMF(8,.3,2)),bF(bBin(8,.3,0,1)),bF(bBin(8,.3,0,2)),bF(1-bBin(8,.3,0,2))],2,['At most two means X ≤ 2, including 0, 1, and 2.','Use X ~ Binomial(n = 8, p = 0.30).','P(X ≤ 2) = P(X = 0) + P(X = 1) + P(X = 2) ≈ '+bF(bBin(8,.3,0,2))+'.'],'Exactly two and fewer than two are different events.',bBinGuide(8,.3,0,2));
bQ(2,'binomial_probability_calculation','A player wins each of 12 independent rounds with probability 0.25. X is the total number of wins.','What is P(X ≥ 4), approximately?',[bF(bPMF(12,.25,4)),bF(bBin(12,.25,5,12)),bF(bBin(12,.25,4,12)),bF(bBin(12,.25,0,3))],2,['At least four means 4 through 12 wins, inclusive.','The complementary event is X ≤ 3.','P(X ≥ 4) = 1 − P(X ≤ 3) ≈ '+bF(bBin(12,.25,4,12))+'.'],'Using 1 − P(X ≤ 4) excludes four wins and answers more than four.',bBinGuide(12,.25,4,12));
bQ(2,'binomial_probability_calculation','A sensor correctly detects an object with probability 0.40 on each of 10 independent tests. X counts the correct detections.','What is the probability of fewer than four correct detections?',[bF(bPMF(10,.4,4)),bF(bBin(10,.4,0,3)),bF(bBin(10,.4,5,10)),bF(bBin(10,.4,0,4))],1,['Fewer than four means X < 4. Since X is a count, this is X ≤ 3.','Use X ~ Binomial(n = 10, p = 0.40).','P(X < 4) = P(X ≤ 3) ≈ '+bF(bBin(10,.4,0,3))+'.'],'A strict inequality requires moving the integer boundary by one.',bBinGuide(10,.4,0,3));
bQ(2,'interpret_mean_of_random_variable','A service request is resolved on the first call with probability 0.65, independently for each of 40 requests. X counts first-call resolutions.','What is the mean of X, and how should it be interpreted?',['26; over many groups of 40 requests, the average count resolved on the first call is about 26.','26; every group of 40 requests contains exactly 26 first-call resolutions.','0.65; the average count resolved in a group of 40 requests is 0.65.','14; the average count resolved on the first call is about 14.'],0,['For a binomial count, μ = np = 40(0.65) = 26.','This is a long-run average count over many groups of 40 requests.','A particular group can have more or fewer than 26 first-call resolutions.'],'Do not confuse the one-request probability with the mean count in 40 requests.',bArithmetic('40*0.65','26','Multiply the fixed number of trials by the success probability.'));
bQ(2,'identify_binomial_quantity_meaning','X counts successes in 60 independent trials, each with success probability 0.40.','Which value is closest to the standard deviation of X?',['3.79','4.90','14.40','24.00'],0,['For a binomial count, σ = √[np(1 − p)].','σ = √[60(0.40)(0.60)] = √14.4 ≈ 3.79 successes.'],'np = 24 is the mean; np(1 − p) = 14.4 is the variance.',bArithmetic('(60*0.4*0.6)^0.5','3.794733192','Use the binomial standard-deviation formula.'));
bQ(2,'most_or_least_likely_binomial_value','A quality-control alarm detects each faulty item with probability 0.90, independently. X counts the detections among 6 faulty items.','Which listed value of X is least likely?',['0','1','5','6'],0,['X ~ Binomial(n = 6, p = 0.90), so counts near 6 are much more likely than counts near 0.','P(X = 0) = (0.10)⁶ = 0.000001.','The probabilities for 1, 5, and 6 detections are 0.000054, 0.354294, and 0.531441, respectively.'],'The most extreme listed value relative to the likely high count is zero, not six.',bArithmetic('0.1^6','0.000001','All six faulty items must go undetected.'));
// 2.B.3: continuous models, empirical rule, normal shape, standard scores.
bQ(3,'discrete_or_continuous_variable','A researcher records several quantities during a day at a greenhouse.','Which variable is best modeled as continuous?',['The number of plants that flower','The number of cracked pots','The elapsed time until a pump stops','The number of seeds in a packet'],2,['Elapsed time is a measurement that can take any value in an interval.','The other quantities are counts with discrete possible values.'],'The phrase number of minutes would still describe measured time, rather than a count of objects.');
bQ(3,'probability_of_single_value_continuous','The fill volume X of a bottle is modeled by a normal distribution with mean 500 mL and standard deviation 4 mL.','Which probability is zero under this continuous model?',['P(X = 500)','P(X < 500)','P(496 < X < 504)','P(X > 512)'],0,['For a continuous variable, probability is area under a density curve over an interval.','A single exact value has zero width and therefore zero area.','P(X = 500) = 0, even though 500 is the mean. The other regions have positive width and positive area.'],'A very small tail probability is still positive in a normal model.');
bQ(3,'empirical_rule_percents_and_bounds','The mass of a certain fruit is approximately normal with mean 180 g and standard deviation 12 g.','Using the empirical rule, approximately what percent of fruits weigh between 168 g and 192 g?',['16%','34%','68%','95%'],2,['The endpoints are 180 − 12 and 180 + 12: one standard deviation on each side of the mean.','The empirical rule places approximately 68% within one standard deviation.'],'34% describes only one half of this central interval.');
bQ(3,'empirical_rule_percents_and_bounds','Battery lifetimes are approximately normal with mean 40 hours and standard deviation 3 hours.','Using the empirical rule, approximately what percent last more than 46 hours?',['2.5%','5%','47.5%','95%'],0,['46 = 40 + 2(3), so the boundary is two standard deviations above the mean.','Approximately 95% lie within two standard deviations, leaving 5% in both tails.','By symmetry the upper tail is approximately 5%/2 = 2.5%.'],'The remaining 5% is split between two tails.');
bQ(3,'empirical_rule_percents_and_bounds','Flight durations on a route are approximately normal with mean 100 minutes and standard deviation 8 minutes.','Using the empirical rule, approximately what percent last at least 92 minutes?',['16%','32%','68%','84%'],3,['92 minutes is one standard deviation below the mean.','Approximately 16% lie below μ − σ.','The area above that boundary is approximately 100% − 16% = 84%.'],'The direction matters: above a below-mean cutoff includes more than half the distribution.');
bQ(3,'empirical_rule_percents_and_bounds','A normally distributed measurement has approximately 95% of its values in the central interval from 42 cm to 66 cm.','What is the approximate standard deviation?',['4','6','8','12'],1,['A central 95% interval extends approximately two standard deviations on each side of the mean.','Its full width is therefore approximately 4σ.','σ ≈ (66 − 42)/4 = 6 cm.'],'The full interval spans four standard deviations, not two.',bArithmetic('(66-42)/4','6','A central 95% interval is about four standard deviations wide.'));
bQ(3,'z_score_calculation','Test scores have mean 72 points and standard deviation 8 points. A student scores 60 points.','What is the student’s z-score?',['−1.50','−0.67','0.67','1.50'],0,['Use z = (x − μ)/σ.','z = (60 − 72)/8 = −1.50.','The score is 1.5 standard deviations below the mean.'],'A score below the mean must have a negative z-score.',bArithmetic('(60-72)/8','-1.5','Subtract the mean before dividing by the standard deviation.'));
bQ(3,'empirical_rule_percents_and_bounds','Z follows the standard normal distribution.','Using the empirical rule, what is P(−1 < Z < 2), approximately?',['0.475','0.680','0.815','0.950'],2,['From z = −1 to 0, the area is approximately 0.34.','From 0 to z = 2, the area is approximately 0.95/2 = 0.475.','Add the disjoint regions: 0.34 + 0.475 = 0.815.'],'The interval is not symmetric about zero. Split it at the mean.');
bQ(3,'normal_distribution_shape','Two normal models have the same mean, 50, but model A has standard deviation 4 and model B has standard deviation 10.','Which comparison is correct?',['A is taller and narrower than B; each curve has total area 1.','B is taller and narrower than A; each curve has total area 1.','A has a greater total area because its peak is taller.','B has a greater total area because it is wider.'],0,['The smaller standard deviation concentrates the same total probability closer to the mean.','Model A is narrower and has a higher peak than model B.','Every probability density curve has total area 1.'],'Curve height is density, not total probability.');
bQ(3,'value_at_percentile_of_normal_distribution','The finishing times of a running event are approximately normal with mean 54 minutes and standard deviation 6 minutes.','Using the empirical rule, which time is approximately the 16th percentile?',['42','48','60','66'],1,['About 16% of a normal distribution lies below μ − σ.','The 16th-percentile time is approximately 54 − 6 = 48 minutes.'],'A lower percentile corresponds to a time below the mean.');
// 2.B.4: normal CDF, inverse normal, unknown parameters, context and tail choices.
bQ(4,'percent_beyond_value_in_normal_distribution','The waiting time X for a laboratory result is approximately normal with mean 50 hours and standard deviation 8 hours.','What is P(X < 44), approximately?',['0.2266','0.2734','0.4533','0.7734'],0,['Standardize the boundary: z = (44 − 50)/8 = −0.75.','The required region is the lower tail.','P(X < 44) = P(Z < −0.75) ≈ 0.2266.'],'0.7734 is the probability above 44 hours; 0.2734 is only the area between 44 and the mean.',bNormGuide(-Infinity,44,50,8));
bQ(4,'percent_beyond_value_in_normal_distribution','The length of a metal rod is approximately normal with mean 50 cm and standard deviation 8 cm.','What proportion of rods are longer than 60 cm?',['0.1056','0.2113','0.3944','0.8944'],0,['The cutoff has z = (60 − 50)/8 = 1.25.','Longer than 60 cm is the upper tail.','P(X > 60) = 1 − Φ(1.25) ≈ 0.1056.'],'A cumulative area to the left must be complemented for an upper-tail question.',bNormGuide(60,Infinity,50,8));
bQ(4,'percent_beyond_value_in_normal_distribution','Daily travel times are approximately normal with mean 30 minutes and standard deviation 5 minutes.','What proportion of travel times are between 25 and 38 minutes?',['0.0548','0.1587','0.7865','0.9452'],2,['The lower and upper z-scores are (25 − 30)/5 = −1 and (38 − 30)/5 = 1.6.','Find the cumulative area through the upper endpoint and subtract the area through the lower endpoint.','P(25 < X < 38) = Φ(1.6) − Φ(−1) ≈ 0.7865.'],'Using only one endpoint includes values outside the requested interval.',bNormGuide(25,38,30,5));
bQ(4,'percent_beyond_value_in_normal_distribution','A machine produces rings with diameters approximately normal with mean 20 mm and standard deviation 0.4 mm. A ring is rejected if its diameter is below 19.6 mm or above 20.8 mm.','Approximately what proportion of rings are rejected?',['0.0228','0.1587','0.1814','0.8186'],2,['The rejection boundaries have z-scores −1 and 2.','Rejection occurs in either of two disjoint tails.','P(reject) = Φ(−1) + 1 − Φ(2) ≈ 0.1587 + 0.0228 = 0.1814.'],'The central interval represents accepted rings, not rejected rings.',bGuide('Normal CD',[['First calculation: Lower','−1 × 10⁹⁹'],['Upper',19.6],['σ',.4],['μ',20]],'0.1587 + 0.0228 ≈ 0.1814','Repeat with Lower = 20.8 and Upper = 1 × 10⁹⁹ to find 0.0228, then add the two tail probabilities.'));
bQ(4,'value_at_percentile_of_normal_distribution','A delivery distance is approximately normal with mean 80 km and standard deviation 12 km.','Which distance is closest to the 90th percentile?',['64.62','81.28','90.80','95.38'],3,['The 90th percentile has 0.90 of the distribution to its left.','Its standard normal value is z ≈ 1.2816.','x = μ + zσ = 80 + 1.2816(12) ≈ 95.38 km.'],'0.90 is an area, not a z-score. Multiplying 12 by 0.90 gives the wrong cutoff.',bInvGuide(.9,80,12));
bQ(4,'value_at_percentile_of_normal_distribution','Completion times are approximately normal with mean 120 seconds and standard deviation 15 seconds.','What time marks the cutoff for the fastest 5% of completions?',['95.33','118.36','121.64','144.67'],0,['Faster means a smaller completion time, so use the lower 5% of the distribution.','The fifth percentile has z ≈ −1.6449.','x = 120 − 1.6449(15) ≈ 95.33 seconds.'],'The slowest 5% are in the upper tail, but the fastest 5% are in the lower tail.',bInvGuide(.05,120,15));
bQ(4,'value_at_percentile_of_normal_distribution','Package masses are approximately normal with mean 1000 g and standard deviation 20 g.','Which interval contains the middle 80%, approximately?',['967.10 to 1032.90','974.37 to 1025.63','980.00 to 1020.00','983.17 to 1016.83'],1,['The middle 80% leaves 10% in each tail.','The endpoints are the 10th and 90th percentiles, with z ≈ ±1.2816.','1000 ± 1.2816(20) gives approximately 974.37 g to 1025.63 g.'],'Using the 80th percentile as the upper endpoint does not produce a central 80% interval.',bGuide('Inverse Normal',[['First cutoff: Tail','Left'],['Area',.1],['σ',20],['μ',1000]],'974.37 g and 1025.63 g','Calculate once with Area = 0.10 and again with Area = 0.90.'));
bQ(4,'normal_parameter_from_percentile','A normal distribution has standard deviation 5 cm. Its 10th percentile is 42 cm.','Which value is closest to its mean?',['35.59','41.50','42.00','48.41'],3,['The 10th percentile has z ≈ −1.2816.','Use x = μ + zσ: 42 = μ − 1.2816(5).','Therefore μ = 42 + 6.408 ≈ 48.41 cm.'],'The 10th percentile lies below the mean. A proposed mean below 42 cm has the wrong direction.',bGuide('Inverse Normal',[['Tail','Left'],['Area',.1],['σ',1],['μ',0]],'z ≈ −1.2816; μ ≈ 48.41 cm','Find the standard normal z-score first. Then solve μ = 42 − z(5).'));
bQ(4,'normal_parameter_from_percentile','The mean of a normal distribution is 75 points. Its 90th percentile is 84 points.','Which equation can be used to find its standard deviation σ?',['1.2816 = (84 − 75)/σ','0.90 = (84 − 75)/σ','−1.2816 = (84 − 75)/σ','1.2816 = (84 − 75)/σ²'],0,['The 90th-percentile z-score is approximately 1.2816.','Standardizing gives z = (x − μ)/σ.','Substitute: 1.2816 = (84 − 75)/σ, so σ ≈ 7.02 points.'],'The denominator of a z-score is the standard deviation, not the variance.',bGuide('Inverse Normal',[['Tail','Left'],['Area',.9],['σ',1],['μ',0]],'z ≈ 1.2816; σ ≈ 7.02','After finding z, calculate (84 − 75)/z.'));
bQ(4,'percent_beyond_value_in_normal_distribution','The mass of a parcel is approximately normal with mean 2.0 kg and standard deviation 0.3 kg. A shipment contains 800 parcels from this process.','Approximately how many parcels are expected to weigh more than 2.45 kg?',['27','53','107','747'],1,['The boundary has z = (2.45 − 2.0)/0.3 = 1.5.','The upper-tail probability is approximately 0.06681.','The expected count is 800(0.06681) ≈ 53 parcels.'],'The question asks for an expected count, not just the probability for one parcel.',bGuide('Normal CD',[['Lower',2.45],['Upper','1 × 10⁹⁹'],['σ',.3],['μ',2]],'p ≈ 0.066807; 800p ≈ 53.45','Keep the unrounded probability before multiplying by 800.'));
// 2.B.5 stays at the introductory scope of the STS lesson: no inference tests.
bQ(5,'identify_population_and_sample','A city has 12,000 households. A researcher selects a random sample of 80 households and records their monthly water use.','What are the population and sample?',['Population: all 12,000 households; sample: the 80 selected households.','Population: the 80 selected households; sample: all 12,000 households.','Population: the city mean water use; sample: the sample mean water use.','Population: all possible sample means; sample: one household’s water use.'],0,['The population is the entire group the researcher wants to learn about.','The sample is the subset actually selected and measured.','Here they are all 12,000 households and the 80 selected households, respectively.'],'Parameters and statistics are numerical summaries, rather than the groups of households.');
bQ(5,'statistic_from_description','A warehouse’s true mean packing time is μ = 18 minutes. A random sample of 50 orders has mean packing time x̄ = 19.2 minutes.','Which statement is correct?',['18 is a statistic and 19.2 is a parameter.','Both values are parameters because both are means.','18 is a parameter and 19.2 is a statistic.','Both values are statistics because packing times vary.'],2,['A parameter summarizes the population; a statistic summarizes a sample.','The true mean for all warehouse orders, μ = 18, is a parameter.','The mean from the 50 sampled orders, x̄ = 19.2, is a statistic.'],'Whether a number is a parameter or statistic depends on the group it summarizes.');
bQ(5,'sampling_distribution_definition','A computer repeatedly takes independent random samples of 25 buses from a large population and calculates the mean delay for each sample.','A histogram of the 2,000 sample means approximates which distribution?',['The delays of all individual buses in the population.','The delays of the 25 buses in the first sample.','The sampling distribution of mean delay for samples of size 2,000.','The sampling distribution of mean delay for samples of size 25.'],3,['Each plotted value is a mean calculated from one sample of 25 buses.','A distribution of a statistic across repeated samples is a sampling distribution.','The sample size is 25; 2,000 is the number of repetitions used to approximate the distribution.'],'Do not confuse the number of simulated samples with the size of each sample.');
bQ(5,'central_limit_theorem_statement','A large population of transaction amounts is moderately right-skewed with finite mean and standard deviation. Independent random samples of 100 transactions are selected.','Which conclusion is justified by the central limit theorem?',['The transaction amounts in every sample will be approximately normal.','The population of transaction amounts becomes approximately normal.','The distribution of sample mean transaction amounts is approximately normal because each sample is large.','Every sample mean must equal the population mean.'],2,['The central limit theorem concerns the sampling distribution of a sample mean.','For a sufficiently large random sample, that distribution is approximately normal even when the population is not normal.','Here n = 100 is large for the stated moderately skewed population.'],'The theorem does not make individual observations or the population normal.');
bQ(5,'reason_sampling_distribution_not_normal','A population of purchase amounts is strongly right-skewed. A simulation takes independent random samples of 4 purchases and plots their means. The simulated distribution remains right-skewed.','What best explains this result?',['The sample size is too small to expect the central limit theorem to remove the strong skewness.','The sample means must all be below the population mean.','A sampling distribution is normal only if at least 4,000 samples are simulated.','Random selection forces a sampling distribution to be uniform.'],0,['The population is strongly skewed and the sample size is only 4.','A small sample mean can retain substantial skewness from the population.','More simulation repetitions reveal the shape more clearly; they do not change the underlying sampling distribution.'],'A sample-size rule of thumb is not a guarantee, especially for severe skewness.');
bQ(5,'sampling_distribution_shape','Individual carton masses follow a normal distribution. Independent random samples of 6 cartons are taken.','What is the shape of the sampling distribution of x̄?',['Normal, because a mean of independent normal observations is normal even when n is small.','Not normal, because 6 is less than 30.','Right-skewed, because masses cannot be negative.','Uniform, because the samples are selected randomly.'],0,['When the population is normal, the sampling distribution of the sample mean is normal for any sample size.','The n ≥ 30 guideline is used when normality must be justified from a non-normal population.'],'A small sample size does not prevent normal sample means when the population itself is normal.');
bQ(5,'sample_size_effect_on_sampling_distribution','Simulation A takes 2,000 independent random samples of size 10 from a population. Simulation B takes 500 independent random samples of size 80 from the same population. Both record sample means.','How should the centers and variability compare?',['The centers are about equal, and B has less variability.','The centers are about equal, and A has less variability because it uses more repetitions.','B has a larger center and less variability.','The centers and variability must both be identical.'],0,['Sample means are centered at the same population mean regardless of the sample size.','A mean from 80 observations varies less from sample to sample than a mean from 10 observations.','The number of simulation repetitions affects how smooth the display looks, rather than the theoretical spread.'],'Distinguish the observations per sample from the number of simulated samples.');
bQ(5,'probability_from_simulation_results','Assuming a claimed population mean of 15 minutes, a computer simulates 1,000 random samples of 40 service times. Of the simulated means, 28 are at least 16.2 minutes. An actual random sample of 40 has mean 16.2 minutes.','What is the estimated probability of a sample mean at least as large as the observed mean, assuming the claim is true?',['0.028','0.280','0.700','0.972'],0,['The event is a simulated sample mean of at least 16.2 minutes.','There are 28 such results among 1,000 repetitions.','Estimated probability = 28/1000 = 0.028.'],'This is a probability of a sample statistic assuming the claim, not the probability that the claim is true.',bArithmetic('28/1000','0.028','Use the number of simulated results in the requested tail over all repetitions.'));
bQ(5,'simulation_based_claim_evaluation','A school claims that its population mean journey time is 25 minutes. Under that claim, 300 of 500 simulated means from random samples of size 40 are at least as large as an observed sample mean of 24.8 minutes.','What is the best conclusion from this comparison?',['The observed mean proves that the population mean is 25 minutes.','The observed mean is not unusual under the claim, so this comparison gives little evidence against the claim.','The observed mean disproves the claim because it differs from 25 minutes.','The probability that the claim is true is exactly 300/500.'],1,['Under the claimed model, the estimated upper-tail probability is 300/500 = 0.60.','An observed mean at least this large is common in the simulation.','The result gives little evidence against the claim, but does not prove the claim true.'],'Sampling variability permits a sample mean to differ from the population mean.');
bQ(5,'sampling_distribution_exact_small_population','A population consists of four values: 2, 4, 6, and 8. Every unordered sample of size 2 without replacement is equally likely.','What is the probability that the sample mean is at least 6?',['1/6','1/3','1/2','2/3'],1,['There are six equally likely samples: (2,4), (2,6), (2,8), (4,6), (4,8), and (6,8).','Their sample means are 3, 4, 5, 5, 6, and 7.','Two of the six means are at least 6, so the probability is 2/6 = 1/3.'],'Sample means are not equally likely as distinct values: 5 arises from two different samples.',bArithmetic('2/6','0.3333333333','Count equally likely samples, including repeated values of the sample mean.'));

