 card.innerHTML='<div class="card-top"><span class="question-badge">Question '+String(i+1).padStart(2,'0')+'</span><span class="within">Lesson '+section+' · '+local+' of 10</span></div><div class="question-content"><div class="question-inner"><p class="scenario">'+q.scenario+'</p>'+q.visual+'<p class="ask" id="'+id+'-ask">'+q.ask+'</p><fieldset aria-labelledby="'+id+'-ask">'+q.options.map((o,j)=>'<label class="option"><input type="radio" name="'+id+'" value="'+'ABCD'[j]+'"><span class="letter">'+'ABCD'[j]+'</span><span class="option-text">'+o+'</span></label>').join('')+'</fieldset></div></div><footer class="card-footer"><span class="choice-status" aria-live="polite">Select an answer, then check your reasoning.</span><button class="solution-trigger" type="button" aria-expanded="false" aria-controls="'+id+'-worked">Solution <span aria-hidden="true">↗</span></button></footer>';
 document.querySelector('.question-area').appendChild(card);cards.push(card);
 const panel=document.createElement('div');panel.className='solution-panel';panel.dataset.index=index;panel.id=id+'-worked';panel.hidden=true;
 panel.innerHTML='<div class="solution-inner"><div class="answer-block"><span class="eyebrow">Correct answer</span><strong>'+key+'</strong><p class="feedback" aria-live="polite" hidden></p></div><h3>Work it through</h3>'+(q.solutionVisual||'')+'<ol>'+q.steps.map(s=>'<li>'+s+'</li>').join('')+'</ol><div class="trap"><h3>Watch the reasoning</h3><p>'+q.trap+'</p></div></div>';
 document.querySelector('.explanation-panels').appendChild(panel);panels.push(panel);
 card.querySelector('.solution-trigger').onclick=()=>animateLayout(()=>revealed?closeSolution():openSolution());card.onchange=()=>{setFeedback();updateProgress();fit()};
